def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    props = s.get('element_properties') or {}
    groups = [(props.get(t.get('element')) or {}).get('group') for t in sites]
    radii = [(props.get(t.get('element')) or {}).get('covalent_radius_A') for t in sites]
    occ = [max(0.0, t.get('occupancy') if t.get('occupancy') is not None else 1.0) for t in sites]
    eligible = [groups[i] is not None and 13 <= groups[i] <= 17 and occ[i] > 0 for i in range(n)]
    total = sum(occ[i] for i in range(n) if eligible[i])
    if total <= 0:
        return 0.0
    parent = list(range(n))
    size = [1 for i in range(n)]
    shift = [[0, 0, 0] for i in range(n)]
    periodic = [False for i in range(n)]
    bonded = [False for i in range(n)]
    for edge in s.get('neighbors') or []:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        image = edge.get('image')
        if not (0 <= i < n and 0 <= j < n and d is not None and 0 < d <= 6):
            continue
        if not eligible[i] or not eligible[j] or image is None or len(image) != 3:
            continue
        a = radii[i]
        b = radii[j]
        if a is None or b is None or a <= 0 or b <= 0 or d > 1.25 * (a + b):
            continue
        ri = i
        di = [0, 0, 0]
        for step in range(n):
            if parent[ri] == ri:
                break
            for k in range(3):
                di[k] += shift[ri][k]
            ri = parent[ri]
        rj = j
        dj = [0, 0, 0]
        for step in range(n):
            if parent[rj] == rj:
                break
            for k in range(3):
                dj[k] += shift[rj][k]
            rj = parent[rj]
        delta = [image[k] + di[k] - dj[k] for k in range(3)]
        if ri == rj:
            bonded[ri] = True
            if any(v != 0 for v in delta):
                periodic[ri] = True
        elif size[ri] >= size[rj]:
            parent[rj] = ri
            shift[rj] = delta
            size[ri] += size[rj]
            periodic[ri] = periodic[ri] or periodic[rj]
            bonded[ri] = True
        else:
            parent[ri] = rj
            shift[ri] = [-v for v in delta]
            size[rj] += size[ri]
            periodic[rj] = periodic[ri] or periodic[rj]
            bonded[rj] = True
    value = 0.0
    for i in range(n):
        if not eligible[i]:
            continue
        root = i
        for step in range(n):
            if parent[root] == root:
                break
            root = parent[root]
        if bonded[root] and not periodic[root]:
            value += occ[i]
    return value / total
